SELECT EXISTS (
    SELECT 1
    FROM public.tb_drafting_work_category
    WHERE tenant_id = #{tenantId}
      AND drafting_work_category_id = #{draftingWorkCategoryId}
      AND use_at = 'Y'
      AND COALESCE(delete_status, 'N') <> 'Y'
)

INSERT INTO public.tb_electronic_approval_main (
    tenant_id, drafting_work_category_id, document_type, eabus_no, document_no, document_status, title,
    contents_json, contents_html, contents_text, drafter_id, drafter_name,
    drafter_department_name, created_at, updated_at, updated_by
) VALUES (
    #{tenantId}, #{draftingWorkCategoryId, jdbcType=BIGINT}, #{documentType}, #{eabusNo}, #{documentNo}, 'DRAFT', #{title},
    CAST(#{contentsJson} AS jsonb), #{contentsHtml}, #{contentsText}, #{drafterId},
    #{drafterName}, #{drafterDepartmentName}, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, #{drafterId}
)
RETURNING electronic_approval_id

SELECT electronic_approval_id, document_type, document_status, drafter_id
FROM public.tb_electronic_approval_main
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND deleted_yn = 'N'
FOR UPDATE

mapper.update:
UPDATE public.tb_electronic_approval_main
SET document_status = #{nextDocumentStatus},
    submitted_at = COALESCE(submitted_at, CURRENT_TIMESTAMP),
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{actorId}
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND document_status = #{expectedDocumentStatus}
  AND deleted_yn = 'N'

UPDATE public.tb_electronic_approval_main
SET document_status = 'DRAFT',
    submitted_at = NULL,
    updated_at = CURRENT_TIMESTAMP,
    updated_by = #{actorId}
WHERE tenant_id = #{tenantId}
  AND electronic_approval_id = #{electronicApprovalId}
  AND drafter_id = #{drafterId}
  AND document_status = 'PENDING'
  AND deleted_yn = 'N'

