mapper.sql:
AND (
    m.drafter_id = #{drafterId}
    OR (
        m.document_status != 'DRAFT'
        AND EXISTS (
            SELECT 1
            FROM public.tb_electronic_approval_line_info l
            WHERE l.tenant_id = m.tenant_id
              AND l.electronic_approval_id = m.electronic_approval_id
              AND l.participant_user_id = #{participantUserId}
        )
    )
)

WHERE m.tenant_id = #{tenantId} AND m.deleted_yn = 'N'
AND EXISTS ( SELECT 1 FROM public.tb_electronic_approval_line_info pending_line WHERE pending_line.tenant_id = m.tenant_id AND pending_line.electronic_approval_id = m.electronic_approval_id AND pending_line.participant_user_id = #{participantUserId} AND pending_line.action_status = 'PENDING' )
AND m.document_status IN ('PENDING', 'IN_PROGRESS')
AND m.drafter_id = #{drafterId} AND m.document_status = 'DRAFT'
AND m.document_status = #{scope}
AND m.electronic_approval_id = #{electronicApprovalIdFilter}
AND m.document_no = #{documentNoFilter}
AND m.document_type = #{documentType}
AND m.electronic_approval_id = #{electronicApprovalId}
AND m.document_status = #{documentStatus}
AND ( m.document_no ILIKE '%' || #{keyword} || '%' OR m.title ILIKE '%' || #{keyword} || '%' OR m.drafter_name ILIKE '%' || #{keyword} || '%' )
AND m.eabus_no ILIKE '%' || #{eabusNoFilter} || '%'
AND m.title ILIKE '%' || #{titleFilter} || '%'
AND m.drafter_name ILIKE '%' || #{drafterNameFilter} || '%'
AND m.drafter_department_name ILIKE '%' || #{drafterDepartmentName} || '%'
AND EXISTS ( SELECT 1 FROM public.tb_electronic_approval_line_info participant_line WHERE participant_line.tenant_id = m.tenant_id AND participant_line.electronic_approval_id = m.electronic_approval_id AND participant_line.participant_name ILIKE '%' || #{participantName} || '%' )
AND m.drafter_id = #{drafterId}
AND EXISTS ( SELECT 1 FROM public.tb_electronic_approval_line_info my_line WHERE my_line.tenant_id = m.tenant_id AND my_line.electronic_approval_id = m.electronic_approval_id AND my_line.participant_user_id = #{participantUserId}
AND my_line.participant_type = #{myParticipantType}
AND my_line.action_status = #{myActionStatus}
)
AND EXISTS ( SELECT 1 FROM public.tb_electronic_approval_line_info pending_line WHERE pending_line.tenant_id = m.tenant_id AND pending_line.electronic_approval_id = m.electronic_approval_id AND pending_line.participant_type IN ('APPROVAL', 'AGREEMENT') AND pending_line.action_status = 'PENDING' AND pending_line.stage_order = ( SELECT MIN(active_line.stage_order) FROM public.tb_electronic_approval_line_info active_line WHERE active_line.tenant_id = m.tenant_id AND active_line.electronic_approval_id = m.electronic_approval_id AND active_line.participant_type IN ('APPROVAL', 'AGREEMENT') AND active_line.action_status = 'PENDING' ) AND pending_line.participant_name ILIKE '%' || #{currentApproverName} || '%' )
AND ( (m.document_status = 'DRAFT' AND m.created_at >= CAST(#{submittedAtFrom} AS date)) OR (m.document_status != 'DRAFT' AND m.submitted_at >= CAST(#{submittedAtFrom} AS date)) )
AND ( (m.document_status = 'DRAFT' AND m.created_at < CAST(#{submittedAtTo} AS date) + INTERVAL '1 day') OR (m.document_status != 'DRAFT' AND m.submitted_at < CAST(#{submittedAtTo} AS date) + INTERVAL '1 day') )
AND m.updated_at >= CAST(#{updatedAtFrom} AS date)
AND m.updated_at < CAST(#{updatedAtTo} AS date) + INTERVAL '1 day'

mapper.select:
SELECT m.electronic_approval_id, m.document_no, m.eabus_no, m.document_type, m.document_status,
       m.title, m.drafter_name, m.created_at, m.updated_at, m.submitted_at,
       LEFT(COALESCE(m.contents_text, ''), 240) AS summary,
       NULL::varchar AS notice_type,
       (m.drafter_id = #{drafterId}) AS is_drafter
FROM public.tb_electronic_approval_main m
WHERE m.tenant_id = #{tenantId}
  AND m.deleted_yn = 'N'


    AND m.document_type = #{documentType}


    AND m.electronic_approval_id = #{electronicApprovalId}


    AND EXISTS (
        SELECT 1
        FROM public.tb_electronic_approval_line_info l
        WHERE l.tenant_id = m.tenant_id
          AND l.electronic_approval_id = m.electronic_approval_id
          AND l.participant_user_id = #{participantUserId}
          AND l.action_status = 'PENDING'
    )


    AND m.document_status IN ('PENDING', 'IN_PROGRESS')


    AND m.drafter_id = #{drafterId}
    AND m.document_status = 'DRAFT'


    AND m.document_status = #{scope}

ORDER BY m.updated_at DESC, m.electronic_approval_id DESC

mapper.sql:
